cuda_src = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <cuda_fp16.h>
#include <c10/cuda/CUDAStream.h>
#include <cute/tensor.hpp>

using namespace cute;

#define MAX_DPL 64  // supports D up to 32*64 = 2048
template<int DPL>
__global__ void flash_attn_kernel_tpl(
    const __half* __restrict__ Q,
    const __half* __restrict__ K,
    const __half* __restrict__ V,
    __half* __restrict__ O,
    int B, int H, int N, int D,
    int block_m,
    float scale)
{
    const int warp_id = threadIdx.x / 32;
    const int lane     = threadIdx.x % 32;
    const int m_tile = blockIdx.x;
    const int h      = blockIdx.y;
    const int b      = blockIdx.z;
    const int m = m_tile * block_m + warp_id;
    if (m >= N) return;
    const int64_t bh_offset = ((int64_t)b * H + h) * (int64_t)N * (int64_t)D;
    const __half* Qptr = Q + bh_offset;
    const __half* Kptr = K + bh_offset;
    const __half* Vptr = V + bh_offset;
    __half*       Optr = O + bh_offset;
    auto mQ = make_tensor(make_gmem_ptr(Qptr), make_shape(N, D), make_stride(D, Int<1>{}));
    auto mK = make_tensor(make_gmem_ptr(Kptr), make_shape(N, D), make_stride(D, Int<1>{}));
    auto mV = make_tensor(make_gmem_ptr(Vptr), make_shape(N, D), make_stride(D, Int<1>{}));
    auto mO = make_tensor(make_gmem_ptr(Optr), make_shape(N, D), make_stride(D, Int<1>{}));
    float q_reg[DPL];
    #pragma unroll
    for (int i = 0; i < DPL; ++i) {
        int d = lane + i * 32;
        q_reg[i] = __half2float(mQ(m, d));
    }
    float acc[DPL];
    #pragma unroll
    for (int i = 0; i < DPL; ++i) acc[i] = 0.0f;
    float m_i = -INFINITY;
    float l_i = 0.0f;
    for (int n = 0; n < N; ++n) {
        float partial = 0.0f;
        #pragma unroll
        for (int i = 0; i < DPL; ++i) {
            int d = lane + i * 32;
            partial += q_reg[i] * __half2float(mK(n, d));
        }
        #pragma unroll
        for (int off = 16; off > 0; off >>= 1) {
            partial += __shfl_xor_sync(0xffffffff, partial, off);
        }
        float score = partial * scale;
        float new_m = fmaxf(m_i, score);
        float correction = __expf(m_i - new_m);
        float p = __expf(score - new_m);
        l_i = l_i * correction + p;
        #pragma unroll
        for (int i = 0; i < DPL; ++i) {
            int d = lane + i * 32;
            float v = __half2float(mV(n, d));
            acc[i] = acc[i] * correction + p * v;
        }
        m_i = new_m;
    }
    float inv_l = 1.0f / l_i;
    #pragma unroll
    for (int i = 0; i < DPL; ++i) {
        int d = lane + i * 32;
        mO(m, d) = __float2half(acc[i] * inv_l);
    }
}
__global__ void flash_attn_kernel_generic(
    const __half* __restrict__ Q,
    const __half* __restrict__ K,
    const __half* __restrict__ V,
    __half* __restrict__ O,
    int B, int H, int N, int D,
    int block_m,
    float scale)
{
    const int warp_id = threadIdx.x / 32;
    const int lane     = threadIdx.x % 32;
    const int m_tile = blockIdx.x;
    const int h      = blockIdx.y;
    const int b      = blockIdx.z;
    const int m = m_tile * block_m + warp_id;
    if (m >= N) return;
    const int64_t bh_offset = ((int64_t)b * H + h) * (int64_t)N * (int64_t)D;
    const __half* Qptr = Q + bh_offset;
    const __half* Kptr = K + bh_offset;
    const __half* Vptr = V + bh_offset;
    __half*       Optr = O + bh_offset;
    auto mQ = make_tensor(make_gmem_ptr(Qptr), make_shape(N, D), make_stride(D, Int<1>{}));
    auto mK = make_tensor(make_gmem_ptr(Kptr), make_shape(N, D), make_stride(D, Int<1>{}));
    auto mV = make_tensor(make_gmem_ptr(Vptr), make_shape(N, D), make_stride(D, Int<1>{}));
    auto mO = make_tensor(make_gmem_ptr(Optr), make_shape(N, D), make_stride(D, Int<1>{}));
    const int D_per_lane = D / 32;
    float q_reg[MAX_DPL];
    #pragma unroll
    for (int i = 0; i < MAX_DPL; ++i) {
        if (i < D_per_lane) {
            int d = lane + i * 32;
            q_reg[i] = __half2float(mQ(m, d));
        }
    }
    float acc[MAX_DPL];
    #pragma unroll
    for (int i = 0; i < MAX_DPL; ++i) acc[i] = 0.0f;
    float m_i = -INFINITY;
    float l_i = 0.0f;
    for (int n = 0; n < N; ++n) {
        float partial = 0.0f;
        #pragma unroll
        for (int i = 0; i < MAX_DPL; ++i) {
            if (i < D_per_lane) {
                int d = lane + i * 32;
                partial += q_reg[i] * __half2float(mK(n, d));
            }
        }
        #pragma unroll
        for (int off = 16; off > 0; off >>= 1) {
            partial += __shfl_xor_sync(0xffffffff, partial, off);
        }
        float score = partial * scale;
        float new_m = fmaxf(m_i, score);
        float correction = __expf(m_i - new_m);
        float p = __expf(score - new_m);
        l_i = l_i * correction + p;
        #pragma unroll
        for (int i = 0; i < MAX_DPL; ++i) {
            if (i < D_per_lane) {
                int d = lane + i * 32;
                float v = __half2float(mV(n, d));
                acc[i] = acc[i] * correction + p * v;
            }
        }
        m_i = new_m;
    }
    float inv_l = 1.0f / l_i;
    #pragma unroll
    for (int i = 0; i < MAX_DPL; ++i) {
        if (i < D_per_lane) {
            int d = lane + i * 32;
            mO(m, d) = __float2half(acc[i] * inv_l);
        }
    }
}
torch::Tensor flash_attn_forward(torch::Tensor Q, torch::Tensor K, torch::Tensor V) {
    TORCH_CHECK(Q.is_cuda() && K.is_cuda() && V.is_cuda(), "Q,K,V must be CUDA tensors");
    TORCH_CHECK(Q.scalar_type() == at::kHalf && K.scalar_type() == at::kHalf && V.scalar_type() == at::kHalf,
                "Q,K,V must be float16");
    TORCH_CHECK(Q.dim() == 4 && K.dim() == 4 && V.dim() == 4, "Q,K,V must be 4D [B,H,N,D]");
    auto Qc = Q.contiguous();
    auto Kc = K.contiguous();
    auto Vc = V.contiguous();
    int64_t B = Qc.size(0);
    int64_t H = Qc.size(1);
    int64_t N = Qc.size(2);
    int64_t D = Qc.size(3);
    TORCH_CHECK(Kc.size(0) == B && Kc.size(1) == H && Kc.size(2) == N && Kc.size(3) == D,
                "K shape must match Q shape");
    TORCH_CHECK(Vc.size(0) == B && Vc.size(1) == H && Vc.size(2) == N && Vc.size(3) == D,
                "V shape must match Q shape");
    TORCH_CHECK(D % 32 == 0, "embedding dimension per head must be divisible by 32");
    TORCH_CHECK((D / 32) <= MAX_DPL, "embedding dimension too large for this kernel");
    auto O = torch::empty_like(Qc);
    const int block_m = 8; // queries per block (one warp per query)
    dim3 block(block_m * 32);
    dim3 grid((unsigned)((N + block_m - 1) / block_m), (unsigned)H, (unsigned)B);
    float scale = 1.0f / sqrtf((float)D);
    cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();
    const int D_per_lane = (int)(D / 32);
    switch (D_per_lane) {
        case 32:
            flash_attn_kernel_tpl<32><<<grid, block, 0, stream>>>(
                reinterpret_cast<const __half*>(Qc.data_ptr<at::Half>()),
                reinterpret_cast<const __half*>(Kc.data_ptr<at::Half>()),
                reinterpret_cast<const __half*>(Vc.data_ptr<at::Half>()),
                reinterpret_cast<__half*>(O.data_ptr<at::Half>()),
                (int)B, (int)H, (int)N, (int)D,
                block_m,
                scale
            );
            break;
        case 16:
            flash_attn_kernel_tpl<16><<<grid, block, 0, stream>>>(
                reinterpret_cast<const __half*>(Qc.data_ptr<at::Half>()),
                reinterpret_cast<const __half*>(Kc.data_ptr<at::Half>()),
                reinterpret_cast<const __half*>(Vc.data_ptr<at::Half>()),
                reinterpret_cast<__half*>(O.data_ptr<at::Half>()),
                (int)B, (int)H, (int)N, (int)D,
                block_m,
                scale
            );
            break;
        case 8:
            flash_attn_kernel_tpl<8><<<grid, block, 0, stream>>>(
                reinterpret_cast<const __half*>(Qc.data_ptr<at::Half>()),
                reinterpret_cast<const __half*>(Kc.data_ptr<at::Half>()),
                reinterpret_cast<const __half*>(Vc.data_ptr<at::Half>()),
                reinterpret_cast<__half*>(O.data_ptr<at::Half>()),
                (int)B, (int)H, (int)N, (int)D,
                block_m,
                scale
            );
            break;
        case 4:
            flash_attn_kernel_tpl<4><<<grid, block, 0, stream>>>(
                reinterpret_cast<const __half*>(Qc.data_ptr<at::Half>()),
                reinterpret_cast<const __half*>(Kc.data_ptr<at::Half>()),
                reinterpret_cast<const __half*>(Vc.data_ptr<at::Half>()),
                reinterpret_cast<__half*>(O.data_ptr<at::Half>()),
                (int)B, (int)H, (int)N, (int)D,
                block_m,
                scale
            );
            break;
        case 2:
            flash_attn_kernel_tpl<2><<<grid, block, 0, stream>>>(
                reinterpret_cast<const __half*>(Qc.data_ptr<at::Half>()),
                reinterpret_cast<const __half*>(Kc.data_ptr<at::Half>()),
                reinterpret_cast<const __half*>(Vc.data_ptr<at::Half>()),
                reinterpret_cast<__half*>(O.data_ptr<at::Half>()),
                (int)B, (int)H, (int)N, (int)D,
                block_m,
                scale
            );
            break;
        case 1:
            flash_attn_kernel_tpl<1><<<grid, block, 0, stream>>>(
                reinterpret_cast<const __half*>(Qc.data_ptr<at::Half>()),
                reinterpret_cast<const __half*>(Kc.data_ptr<at::Half>()),
                reinterpret_cast<const __half*>(Vc.data_ptr<at::Half>()),
                reinterpret_cast<__half*>(O.data_ptr<at::Half>()),
                (int)B, (int)H, (int)N, (int)D,
                block_m,
                scale
            );
            break;
        default:
            flash_attn_kernel_generic<<<grid, block, 0, stream>>>(
                reinterpret_cast<const __half*>(Qc.data_ptr<at::Half>()),
                reinterpret_cast<const __half*>(Kc.data_ptr<at::Half>()),
                reinterpret_cast<const __half*>(Vc.data_ptr<at::Half>()),
                reinterpret_cast<__half*>(O.data_ptr<at::Half>()),
                (int)B, (int)H, (int)N, (int)D,
                block_m,
                scale
            );
            break;
    }
    auto err = cudaGetLastError();
    TORCH_CHECK(err == cudaSuccess, "flash_attn_kernel launch failed: ", cudaGetErrorString(err));
    return O;
}
"""

flash_attn_ext = load_inline(
    name="cute_flash_attn_ext",
    cpp_sources=cuda_decl,
    cuda_sources=cuda_src,
    functions=["flash_attn_forward"],
    extra_cflags=["-O3"],
    extra_cuda_cflags=["-O3"],
    extra_include_paths=[
        "/root/cutegen_test/cutegen/cutlass/include",
        "/root/cutegen_test/cutegen/cutlass/include/cute/",
    ],
    verbose=False,
)


class ModelNew(nn.Module):
    def __init__(self):
        super().__init__()
        self._ext = flash_attn_ext

    def forward(self, Q: torch.Tensor, K: torch.Tensor, V: torch.Tensor) -> torch.Tensor:
        return self._ext.flash_attn_forward(Q, K, V)

